window.TEST={"sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–10</b></p>\n<p class=\"instruction\"><i>Complete the sentences below.</i></p>\n<p class=\"instruction\"><i>Write </i><i><b>NO MORE THAN THREE WORDS AND/OR A NUMBER</b></i><i> for each answer.</i></p>\n<p class=\"subheading\"><u><i>Example</i></u><i>:   Jim wants to find out about a </i><i><b>room</b></i><i> </i></p>\n<p class=\"\"><span class=\"qnum\">1</span>Jim&#x27;s weekly rent will be $ <input class=\"gap\" data-q=\"1\" aria-label=\"Câu 1\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"\"><span class=\"qnum\">2</span>Jim can park his car in the <input class=\"gap\" data-q=\"2\" aria-label=\"Câu 2\" autocomplete=\"off\" spellcheck=\"false\">  </p>\n<p class=\"\"><span class=\"qnum\">3</span>The telephone is in the <input class=\"gap\" data-q=\"3\" aria-label=\"Câu 3\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"\"><span class=\"qnum\">4</span>Jim will bring a <input class=\"gap\" data-q=\"4\" aria-label=\"Câu 4\" autocomplete=\"off\" spellcheck=\"false\"> for his bedroom.</p>\n<p class=\"\"><span class=\"qnum\">5</span>Peter would like Jim to bring a <input class=\"gap\" data-q=\"5\" aria-label=\"Câu 5\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"\"><span class=\"qnum\">6</span>Peter and Jim will probably watch TV on  <input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"\"><span class=\"qnum\">7</span>Jim works in a <input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\">  twice a week.</p>\n<p class=\"\"><span class=\"qnum\">8</span>Peter will share the cost of <input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\"> with Jim.</p>\n<p class=\"\"><span class=\"qnum\">9</span>Peter wants Jim to move in by  <input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\">. </p>\n<p class=\"\"><span class=\"qnum\">10</span>Jim agrees to move in after his <input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\">.</p>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 11–17</b></p>\n<p class=\"instruction\"><i>Complete the sentences below.</i></p>\n<p class=\"instruction\"><i>Write </i><i><b>NO MORE THAN THREE WORDS AND/OR A NUMBER</b></i><i> for each answer.</i></p>\n<p class=\"subheading\"><b>Spring Down Junior School</b></p>\n<p class=\"\"><span class=\"qnum\">11</span>The school day starts at  <input class=\"gap\" data-q=\"11\" aria-label=\"Câu 11\" autocomplete=\"off\" spellcheck=\"false\"> with registration, and finishes at 4 p.m.</p>\n<p class=\"\"><span class=\"qnum\">12</span>The school canteen offers a  <input class=\"gap\" data-q=\"12\" aria-label=\"Câu 12\" autocomplete=\"off\" spellcheck=\"false\">  for lunch.</p>\n<p class=\"\"><span class=\"qnum\">13</span>The morning and afternoon breaks each last for <input class=\"gap\" data-q=\"13\" aria-label=\"Câu 13\" autocomplete=\"off\" spellcheck=\"false\">.</p>\n<p class=\"\"><span class=\"qnum\">14</span>On Thursday afternoons all children must take part in <input class=\"gap\" data-q=\"14\" aria-label=\"Câu 14\" autocomplete=\"off\" spellcheck=\"false\">.</p>\n<p class=\"\"><span class=\"qnum\">15</span>Every term the children do a special <input class=\"gap\" data-q=\"15\" aria-label=\"Câu 15\" autocomplete=\"off\" spellcheck=\"false\">.</p>\n<p class=\"\"><span class=\"qnum\">16</span>The children are given tests each <input class=\"gap\" data-q=\"16\" aria-label=\"Câu 16\" autocomplete=\"off\" spellcheck=\"false\">.</p>\n<p class=\"\"><span class=\"qnum\">17</span>The children can go to  <input class=\"gap\" data-q=\"17\" aria-label=\"Câu 17\" autocomplete=\"off\" spellcheck=\"false\"> after school to learn new skills such as music.</p>\n<p class=\"subheading\"><b>Questions 18–20</b></p>\n<p class=\"instruction\"><i>Label the plan below.</i></p>\n<p class=\"instruction\"><i>Choose </i><i><b>THREE</b></i><i> correct answers, </i><i><b>A-G</b></i><i>, next to questions </i><i><b>18-20</b></i><i>.</i></p>"}, {"number": 3, "html": ""}, {"number": 4, "html": "<p class=\"subheading\"><b>Questions 31–40</b></p>\n<p class=\"instruction\"><i>Complete the notes below.</i></p>\n<p class=\"instruction\"><i>Write </i><i><b>ONE WORD ONLY</b></i><i> for each answer.</i></p>\n<p class=\"subheading\"><b>Dormancy</b></p>\n<p class=\"\">Organisms enter a state of dormancy, or inactivity, to:</p>\n<p class=\"\"><span class=\"qnum\">31</span>save available  <b> </b><input class=\"gap\" data-q=\"31\" aria-label=\"Câu 31\" autocomplete=\"off\" spellcheck=\"false\"> </p>\n<p class=\"\">reduce demands on their environment</p>\n<p class=\"subheading\"><b>Value of dormancy</b></p>\n<p class=\"\">Organisms which become dormant:</p>\n<p class=\"\"><span class=\"qnum\">32</span>can live in conditions which are environmentally  <b> </b><input class=\"gap\" data-q=\"32\" aria-label=\"Câu 32\" autocomplete=\"off\" spellcheck=\"false\"> </p>\n<p class=\"\">can live in a wider range of places</p>\n<p class=\"\"><span class=\"qnum\">33</span>have less  <b> </b><input class=\"gap\" data-q=\"33\" aria-label=\"Câu 33\" autocomplete=\"off\" spellcheck=\"false\">  from other animals</p>\n<p class=\"subheading\"><b>Causes of dormancy</b></p>\n<p class=\"\"><span class=\"qnum\">34</span>changes in temperature and  <b> </b><input class=\"gap\" data-q=\"34\" aria-label=\"Câu 34\" autocomplete=\"off\" spellcheck=\"false\"> </p>\n<p class=\"\">availability of food, water, oxygen</p>\n<p class=\"subheading\"><b>Dormancy in insects</b></p>\n<p class=\"\"><span class=\"qnum\">35</span>There may be a  <b> </b><input class=\"gap\" data-q=\"35\" aria-label=\"Câu 35\" autocomplete=\"off\" spellcheck=\"false\">  in their metabolism (diapause)</p>\n<p class=\"\">Diapause occurs during extreme conditions, or as part of the life cycle</p>\n<p class=\"subheading\"><b>The African lungfish</b></p>\n<p class=\"\"><span class=\"qnum\">36</span>It buries itself in the  <b> </b><input class=\"gap\" data-q=\"36\" aria-label=\"Câu 36\" autocomplete=\"off\" spellcheck=\"false\">  and creates a slimy cocoon</p>\n<p class=\"\"><span class=\"qnum\">37</span>Two dangers:  <b> </b><input class=\"gap\" data-q=\"37\" aria-label=\"Câu 37\" autocomplete=\"off\" spellcheck=\"false\">  and desiccation</p>\n<p class=\"subheading\"><b>Snails</b></p>\n<p class=\"\">Some close their shells with a membrane during dormancy</p>\n<p class=\"\"><span class=\"qnum\">38</span>Light-coloured shells reflect sunlight and limit  <b> </b><input class=\"gap\" data-q=\"38\" aria-label=\"Câu 38\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"subheading\"><b>Hibernation</b></p>\n<p class=\"\">Only warm-blooded animals hibernate</p>\n<p class=\"subheading\"><b>The Arctic ground squirrel</b></p>\n<p class=\"\"><span class=\"qnum\">39</span>It hibernates in an insulated, underground  <b> </b><input class=\"gap\" data-q=\"39\" aria-label=\"Câu 39\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"\">It loses 40% of its weight during hibernation</p>\n<p class=\"\"><span class=\"qnum\">40</span>When it wakes up, the first part of the body to heat up is the  <b> </b><input class=\"gap\" data-q=\"40\" aria-label=\"Câu 40\" autocomplete=\"off\" spellcheck=\"false\">  </p>"}], "singles": [{"n": 21, "prompt": "What do the students agree about defining forensic linguistics?", "options": ["The dictionary definition was not very useful.", "They could provide an example of the kind of work involved.", "They should read about the subject to see how it is described."]}, {"n": 22, "prompt": "Jen thinks it will be difficult to analyse the voice recording because", "options": ["it is not of good quality.", "the accent is difficult to understand.", "she doesn't know if the speaker is male or female."]}, {"n": 23, "prompt": "Why does Jen think that the 'suspect' might vary their voice patterns?", "options": ["because they're being recorded.", "because they've been told to.", "because they feel uncomfortable about their accent."]}, {"n": 24, "prompt": "What does Rob think about Jen's approach to study?", "options": ["She worries too much about her ability.", "She often ignores the most important issues.", "She has trouble getting started."]}], "pairs": [{"n": 25, "prompt": "Which TWO books do Jen and Rob decide to get from the library?", "options": ["Voice Identification", "Modern Forensic Techniques", "Language and Crime", "Forensics Today", "Research Methods in Forensic Linguistics"]}, {"n": 27, "prompt": "Which TWO practical considerations are both Jen and Rob concerned about?", "options": ["how much time they have for writing up the project", "being able to do enough research", "only speaking to the 'suspect' once", "using recording equipment", "how easy it will be to contact the 'suspect'"]}, {"n": 29, "prompt": "Which TWO sections of the project will Rob write alone?", "options": ["Methodology", "Literature review", "Introduction", "Analysis", "Discussion and conclusions"]}], "answers": {"1": ["80"], "2": ["garage"], "3": ["kitchen"], "4": ["heater"], "5": ["toaster"], "6": ["Friday evening"], "7": ["supermarket"], "8": ["petrol"], "9": ["1st of June", "1st June", "June 1st", "1 June", "June 1"], "10": ["exam"], "11": ["8:55", "8.55", "8:55 a.m.", "8.55 a.m."], "12": ["hot meal"], "13": ["15 minutes"], "14": ["sports"], "15": ["poster"], "16": ["month"], "17": ["clubs"], "18": ["E"], "19": ["A"], "20": ["G"], "21": ["B"], "22": ["A"], "23": ["B"], "24": ["A"], "25": ["B/E"], "26": ["E/B"], "27": ["A/D"], "28": ["D/A"], "29": ["C/E"], "30": ["E/C"], "31": ["resources"], "32": ["stressful"], "33": ["competition"], "34": ["light"], "35": ["reduction"], "36": ["mud"], "37": ["starvation"], "38": ["evaporation"], "39": ["nest"], "40": ["heart"]}};